  "Productos de Belleza y Cosmética": "BC",
};

const sinAcentos = (texto) => texto.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
const normalizar = (texto) =>
  sinAcentos(texto)
    .replace(/[^a-z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
const mnemonicode = (nombre) => {
  const palabras = normalizar(nombre).split(" ").filter((palabra) => palabra && !/^\d+$/.test(palabra));
